1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
8	
9	/**
10	 * Rewrites the create body's telephone into E.164 form. Keeps a leading '+' and its
11	 * country code when present; otherwise assumes '+61' and drops a single leading '0'
12	 * from the national digits. Spaces, dashes and brackets are stripped and 8 to 15
13	 * digits are required after the '+', so anything else is a 400. The national-number
14	 * length is also checked against the country code ('+61' => 9 national digits, '+1' =>
15	 * 10); a wrong length for the country is a 400. Runs before
16	 * {@link BuildOwner} validates, so the stored value is the E.164 string.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
21	        String raw = request.getTelephone().trim();
22	        String digits = raw.replaceAll("\\D", "");
23	        if (!raw.startsWith("+")) {
24	            if (digits.startsWith("0")) {
25	                digits = digits.substring(1);
26	            }
27	            digits = "61" + digits;
28	        }
29	        if (digits.length() < 8 || digits.length() > 15) {
30	            throw new MissingOwnerFieldsException(List.of("telephone"));
31	        }
32	        // Per-country national-number length: '+61' needs 9 national digits, '+1' needs 10.
33	        if (digits.startsWith("61") && digits.length() - 2 != 9
34	                || digits.startsWith("1") && digits.length() - 1 != 10) {
35	            throw new MissingOwnerFieldsException(List.of("telephone"));
36	        }
37	        request.setTelephone("+" + digits);
38	    }
39	}
