9	/**
10	 * Rejects a create body whose email domain is on the disposable-domain blocklist, so the
11	 * endpoint responds 400. An absent or blank email is accepted. Runs after
12	 * {@link NormalizeOwnerEmail}, which has already lower-cased and syntax-checked the value.
13	 */
14	public class RejectDisposableEmailDomain {
15	
16	    private static final Set<String> BLOCKED =
17	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
18	
19	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
20	        String email = request.getEmail();
21	        if (email == null || email.isBlank()) {
22	            return;
23	        }
24	        String domain = email.substring(email.indexOf('@') + 1);
25	        if (BLOCKED.contains(domain)) {
26	            throw new DisposableEmailDomainException(email);
27	        }
28	    }
29	}
