1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Rewrites the create body's address into a canonical form: trimmed with collapsed
10	 * whitespace, upper-cased, and common street-type abbreviations expanded (ST-&gt;STREET,
11	 * RD-&gt;ROAD, AVE-&gt;AVENUE). The structured {@code addressLine1}/{@code addressLine2}
12	 * fields are preferred when supplied: each is normalized and {@code address} is set to
13	 * the composed line 1 (plus a single space and line 2 when present); otherwise the flat
14	 * {@code address} is normalized in place. Runs before {@link BuildOwner}, so the
15	 * persisted and returned values are already normalized. {@link RequireOwnerFields} runs
16	 * first and rejects a body with neither address form, so a value is always present here.
17	 */
18	public class NormalizeOwnerAddress {
19	
20	    private static final Map<String, String> ABBREVIATIONS =
21	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
22	
23	    public void service(@Val OwnerFieldsDto request) {
24	        String line1 = normalize(request.getAddressLine1());
25	        if (line1 != null) {
26	            String line2 = normalize(request.getAddressLine2());
27	            request.setAddressLine1(line1);
28	            request.setAddressLine2(line2);
29	            request.setAddress(line2 == null ? line1 : line1 + " " + line2);
30	        } else {
31	            request.setAddress(normalize(request.getAddress()));
32	        }
33	    }
34	
35	    private static String normalize(String value) {
36	        if (value == null || value.isBlank()) {
37	            return null;
38	        }
39	        StringBuilder normalized = new StringBuilder();
40	        for (String word : value.trim().toUpperCase().split("\\s+")) {
41	            if (normalized.length() > 0) {
42	                normalized.append(' ');
43	            }
44	            normalized.append(ABBREVIATIONS.getOrDefault(word, word));
45	        }
46	        return normalized.toString();
47	    }
48	}
