8	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;
9	
10	/**
11	 * Consolidated duplicate check: rejects a create body whose whole {@link IdentityKey}
12	 * (normalized telephone + email) already belongs to another owner, so the endpoint
13	 * responds 409. Runs after the normalize steps so the key is built from canonical
14	 * values. A full-key match implies the telephones match, so it reuses
15	 * {@link DuplicateOwnerTelephoneException}.
16	 */
17	public class RejectDuplicateOwnerIdentity {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateOwnerTelephoneException {
21	        String key = IdentityKey.of(request.getTelephone(), request.getEmail());
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (Boolean.TRUE.equals(existing.getDeleted())) {
24	                continue;
25	            }
26	            if (key.equals(IdentityKey.of(existing.getTelephone(), existing.getEmail()))) {
27	                throw new DuplicateOwnerTelephoneException(request.getTelephone());
28	            }
29	        }
30	    }
31	}
