8	/**
9	 * Rejects a create body whose city already holds 50 or more owners (compared
10	 * case-insensitively), so the endpoint responds 409.
11	 */
12	public class RejectCrowdedCity {
13	
14	    private static final int CAPACITY = 50;
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws CrowdedCityException {
18	        String city = request.getCity();
19	        long count = ownerRepository.findAll().stream()
20	                .filter(o -> city.equalsIgnoreCase(o.getCity()))
21	                .count();
22	        if (count >= CAPACITY) {
23	            throw new CrowdedCityException(city);
24	        }
25	    }
26	}
