1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.mapper.Locality;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
9	
10	/**
11	 * Rejects a create body whose 4-digit postcode falls outside the range fixed for the
12	 * city's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), so the endpoint responds
13	 * 400. The postcode is optional: an absent value is accepted, and a city with no known
14	 * region ({@link Locality#of} returns {@code UNKNOWN}) accepts any 4-digit value. The
15	 * 4-digit format itself is enforced by bean validation on the body.
16	 */
17	public class RejectInvalidPostcode {
18	
19	    private static final Map<String, int[]> REGION_RANGE = Map.of(
20	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
21	
22	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
23	        String postcode = request.getPostcode();
24	        if (postcode == null) {
25	            return;
26	        }
27	        if (!postcode.matches("[0-9]{4}")) {
28	            throw new InvalidPostcodeException(postcode, request.getCity());
29	        }
30	        int[] range = REGION_RANGE.get(Locality.of(request.getCity()));
31	        if (range == null) {
32	            return;
33	        }
34	        int value = Integer.parseInt(postcode);
35	        if (value < range[0] || value > range[1]) {
36	            throw new InvalidPostcodeException(postcode, request.getCity());
37	        }
38	    }
39	}
