3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.mapper.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's {@code customerCode} formatted {@code <REGION>-<HASH8>}: the region
13	 * derived from the postcode, plus the first 8 upper-case hex characters of the SHA-256 of
14	 * the normalized telephone concatenated with the last name. It carries no sequence number,
15	 * so it is a pure function of the owner's own fields and needs no repository lookup.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        String region = Locality.of(owner.getPostcode(), owner.getCity());
21	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
22	        owner.setCustomerCode(region + "-" + hash8);
23	    }
24	
25	    private static String hash8(String value) {
26	        try {
27	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder();
29	            for (int i = 0; i < 4; i++) {
30	                sb.append(String.format("%02X", digest[i]));
31	            }
32	            return sb.toString();
33	        } catch (NoSuchAlgorithmException e) {
34	            throw new IllegalStateException(e);
35	        }
36	    }
37	}
