4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners already shared this owner's first and last name
9	 * (compared case-insensitively) at creation time, exposed as {@code namesakeCount}.
10	 * Runs before the new owner is saved, so it counts only pre-existing owners.
11	 */
12	public class CountNamesakes {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = key(owner.getFirstName());
16	        String lastName = key(owner.getLastName());
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (firstName.equals(key(existing.getFirstName()))
20	                    && lastName.equals(key(existing.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    private static String key(String value) {
28	        return value == null ? "" : value.trim().toLowerCase();
29	    }
30	}
