1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.HouseholdId;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Flags a new owner as a soft duplicate when an existing owner shares its householdId
11	 * (last name and postcode) but has a different telephone — a likely household match that
12	 * is not a hard duplicate. Records {@code possibleDuplicateOf} with the matching owner's
13	 * id, or leaves the flag false when there is no such match. A declared household member
14	 * ({@code sharesHousehold} true) is never flagged. Runs before the new owner is saved, so
15	 * it inspects only pre-existing owners.
16	 */
17	public class DetectPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
20	        owner.setPossibleDuplicate(false);
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))
27	                    && !key(owner.getTelephone()).equals(key(existing.getTelephone()))) {
28	                owner.setPossibleDuplicate(true);
29	                owner.setPossibleDuplicateOf(existing.getId());
30	                return;
31	            }
32	        }
33	    }
34	
35	    private static String key(String value) {
36	        return value == null ? "" : value.trim().toLowerCase();
37	    }
38	}
