6	/**
7	 * Rolls a date forward onto a business day: weekends and listed public holidays
8	 * roll forward to the next non-holiday weekday, while any other weekday is
9	 * returned unchanged.
10	 */
11	public final class BusinessDay {
12	
13	    private static final Set<LocalDate> HOLIDAYS = Set.of(
14	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
15	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
16	            LocalDate.parse("2026-12-28"));
17	
18	    private BusinessDay() {
19	    }
20	
21	    public static LocalDate onOrAfter(LocalDate date) {
22	        while (date.getDayOfWeek().getValue() > 5 || HOLIDAYS.contains(date)) {
23	            date = date.plusDays(1);
24	        }
25	        return date;
26	    }
27	}
