6	
7	/**
8	 * Signals a bulk signup: true once more than 80 owners have already been created on the
9	 * current business day (by registrationDate), otherwise false.
10	 */
11	public final class BulkSignup {
12	
13	    private static final int THRESHOLD = 80;
14	
15	    private BulkSignup() {
16	    }
17	
18	    public static boolean warns(OwnerRepository ownerRepository) {
19	        LocalDate today = BusinessDay.onOrAfter(LocalDate.now());
20	        long count = ownerRepository.findAll().stream()
21	                .filter(o -> today.equals(o.getRegistrationDate()))
22	                .count();
